import{_ as t,o as r,c as a,a2 as i}from"./chunks/framework.BWuWLRhz.js";const p=JSON.parse('{"title":"Domain and Feature Review Procedure","description":"","frontmatter":{},"headers":[],"relativePath":"architecture/package-review.md","filePath":"architecture/package-review.md","lastUpdated":null}'),n={name:"architecture/package-review.md"};function o(d,e,s,c,l,u){return r(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="domain-and-feature-review-procedure" tabindex="-1">Domain and Feature Review Procedure <a class="header-anchor" href="#domain-and-feature-review-procedure" aria-label="Permalink to &quot;Domain and Feature Review Procedure&quot;">​</a></h1><p><strong>Status:</strong> Active<br><strong>Date:</strong> 2026-07-28<br><strong>Beads issue:</strong> <code>archie-core-5d7</code></p><h2 id="purpose" tabindex="-1">Purpose <a class="header-anchor" href="#purpose" aria-label="Permalink to &quot;Purpose&quot;">​</a></h2><p>Architecture work proceeds one domain or feature at a time. Before any design question, the selected area is researched across its complete live implementation, consumers, tests, state, configuration, and runtime wiring.</p><p>Existing packages are evidence, not the unit that drives the interview. Placement follows behaviour and ownership, not the existing directory name.</p><p>No restructuring implementation begins until the relevant package decisions are agreed and recorded in the focused domain or requirement document.</p><h2 id="required-research" tabindex="-1">Required research <a class="header-anchor" href="#required-research" aria-label="Permalink to &quot;Required research&quot;">​</a></h2><p>Before design questions, the current-state report MUST identify:</p><ul><li>entry points and runtime composition;</li><li>state, persistence, and lifecycle;</li><li>public and internal contracts;</li><li>commands, events, and policy enforcement;</li><li>configuration and defaults;</li><li>all consumers and cross-domain interactions;</li><li>process and infrastructure boundaries;</li><li>tests, failure behaviour, and known invariants;</li><li>duplicated or conflicting implementations;</li><li>documentation that disagrees with live code.</li></ul><p>Discoverable facts MUST be investigated rather than presented to the user as design questions.</p><h2 id="required-decisions" tabindex="-1">Required decisions <a class="header-anchor" href="#required-decisions" aria-label="Permalink to &quot;Required decisions&quot;">​</a></h2><p>Each package review records:</p><table tabindex="0"><thead><tr><th>Decision</th><th>Required result</th></tr></thead><tbody><tr><td>Owned behaviour</td><td>The cohesive job the code performs</td></tr><tr><td>Domain ownership</td><td>The owner of the behaviour and vocabulary</td></tr><tr><td>Final location</td><td>Its target path</td></tr><tr><td>Public contracts</td><td>The smallest interfaces, commands, and events exposed</td></tr><tr><td>Required services</td><td>Domain-defined interfaces implemented by infrastructure</td></tr><tr><td>State ownership</td><td>The owner of each mutable record and transition</td></tr><tr><td>Dependencies</td><td>Allowed imports and dependencies to remove</td></tr><tr><td>Duplication</td><td>Code to consolidate, delete, or keep separate</td></tr><tr><td>Plugin status</td><td>Core domain, shared contract, infrastructure, plugin, or extra</td></tr><tr><td>Process boundary</td><td>In-process, or the concrete reason for isolation</td></tr><tr><td>Configuration</td><td>Settings owned by the domain or plugin</td></tr><tr><td>Policy</td><td>Definitions, evaluators, consequences, and shared mechanics used</td></tr><tr><td>Documentation</td><td>Authoritative definitions and generated reference</td></tr><tr><td>Migration constraints</td><td>Behaviour and data that must remain correct</td></tr></tbody></table><h2 id="interview-method" tabindex="-1">Interview method <a class="header-anchor" href="#interview-method" aria-label="Permalink to &quot;Interview method&quot;">​</a></h2><p>For every selected domain or feature:</p><ol><li>Declare the single area under review.</li><li>Complete the current-state research.</li><li>Explain actual behaviour in plain technical language.</li><li>Separate facts from design decisions and concerns.</li><li>Resolve obvious consequences directly and ask only questions whose answer materially changes behaviour or structure.</li><li>Record each confirmed decision in its focused document.</li><li>Complete that area&#39;s handoff before selecting another.</li><li>Keep unrelated domains outside the implementation scope.</li></ol>',16)])])}const m=t(n,[["render",o]]);export{p as __pageData,m as default};
